mapper.sql:
SELECT ROW_NUMBER() OVER (ORDER BY RBRC.REG_DTTM DESC) AS "LINE_NO" , RBRC.RUBRIC_ID , RBRC.ORG_ID , ORG.ORGNM , ORG.ORGNM AS ORG_NM , RBRC.USER_ID , RBRC.RUBRIC_TTL , RBRC.RUBRIC_QSTN_CNT , RBRC.RUBRIC_TYCD , RGTR.USERNM AS "RGTRNM" , RBRC.REG_DTTM , RBRC.USEYN FROM TB_LMS_RUBRIC RBRC JOIN TB_LMS_ORG ORG ON RBRC.ORG_ID = ORG.ORG_ID JOIN TB_LMS_USER RGTR ON RBRC.RGTR_ID = RGTR.USER_ID WHERE RBRC.UP_RUBRIC_ID IS NULL AND RBRC.RUBRIC_TYCD = 'ORG' AND RBRC.DELYN = 'N'
AND RBRC.ORG_ID = #{orgId}
AND RBRC.RUBRIC_TTL LIKE '%' || #{rubricTtl} || '%'

mapper.select:
SELECT O.ORG_ID , O.ORGNM , O.ORGNM AS ORG_NM , O.ORG_SHRTNM , O.ORG_SHRTNM AS ORG_SHRT_NM , O.ORG_TYCD FROM TB_LMS_ORG O WHERE NVL(O.USEYN, 'Y') = 'Y'
AND O.ORG_ID = #{orgId}
ORDER BY O.ORGNM ASC

mapper.insert:
INSERT INTO TB_LMS_RUBRIC
    ( RUBRIC_ID
    , ORG_ID
    , USER_ID
    , RUBRIC_TTL
    , RUBRIC_QSTN_CNT
    , RUBRIC_TYCD
    , USEYN
    , RGTR_ID
    , REG_DTTM )
VALUES
    ( #{rubricId}
    , #{orgId}
    , #{userId}
    , #{rubricTtl}
    , #{rubricQstnCnt}
    , #{rubricTycd}
    , 'Y'
    , #{rgtrId}
    , FN_DTTM() )

INSERT INTO TB_LMS_RUBRIC_QSTN
    ( RUBRIC_QSTN_ID
    , RUBRIC_ID
    , RUBRIC_QSTN_TTL
    , RUBRIC_QSTN_SEQNO
    , EVLRT
    , RUBRIC_EVL_TYCD
    , RGTR_ID
    , REG_DTTM

    , MDFR_ID
    , MOD_DTTM

    )
VALUES
    ( #{rubricQstnId}
    , #{rubricId}
    , #{rubricQstnTtl}
    , #{rubricQstnSeqno}
    , #{evlrt}
    , #{rubricEvlTycd}
    , #{rgtrId}
    , FN_DTTM()

    , #{mdfrId}
    , FN_DTTM()

    )

INSERT INTO TB_LMS_RUBRIC_VWITM
    ( RUBRIC_VWITM_ID
    , RUBRIC_QSTN_ID
    , RUBRIC_VWITM_TTL
    , RUBRIC_VWITM_PNT
    , RUBRIC_VWITM_SEQNO
    , RGTR_ID
    , REG_DTTM

    , MDFR_ID
    , MOD_DTTM

    )
VALUES
    ( #{rubricVwitmId}
    , #{rubricQstnId}
    , #{rubricVwitmTtl}
    , #{rubricVwitmPnt}
    , #{rubricVwitmSeqno}
    , #{rgtrId}
    , FN_DTTM()

    , #{mdfrId}
    , FN_DTTM()

    )

mapper.select:
SELECT QSTN.RUBRIC_QSTN_ID , QSTN.RUBRIC_QSTN_TTL , QSTN.EVLRT , QSTN.RUBRIC_EVL_TYCD , VWITM.RUBRIC_VWITM_ID , VWITM.RUBRIC_VWITM_TTL , VWITM.RUBRIC_VWITM_PNT , VWITM.RUBRIC_VWITM_SEQNO FROM TB_LMS_RUBRIC RBRC JOIN TB_LMS_RUBRIC_QSTN QSTN ON RBRC.RUBRIC_ID = QSTN.RUBRIC_ID JOIN TB_LMS_RUBRIC_VWITM VWITM ON QSTN.RUBRIC_QSTN_ID = VWITM.RUBRIC_QSTN_ID WHERE RBRC.RUBRIC_ID = #{rubricId} AND RBRC.RUBRIC_TYCD = 'ORG' AND RBRC.DELYN = 'N'
AND RBRC.ORG_ID = #{orgId}
ORDER BY QSTN.RUBRIC_QSTN_SEQNO , VWITM.RUBRIC_VWITM_SEQNO ASC

mapper.update:
UPDATE TB_LMS_RUBRIC
SET
    RUBRIC_TTL = #{rubricTtl}
    , RUBRIC_QSTN_CNT = #{rubricQstnCnt}
    , MDFR_ID = #{mdfrId}
    , MOD_DTTM = FN_DTTM()
WHERE
    RUBRIC_ID = #{rubricId}
    AND ORG_ID = #{orgId}
    AND RUBRIC_TYCD = 'ORG'

UPDATE TB_LMS_RUBRIC
SET
    USEYN = #{useyn}
    , MDFR_ID = #{mdfrId}
    , MOD_DTTM = FN_DTTM()
WHERE
    RUBRIC_ID = #{rubricId}
    AND ORG_ID = #{orgId}
    AND RUBRIC_TYCD = 'ORG'

UPDATE TB_LMS_RUBRIC
SET
    DELYN = 'Y'
    , MDFR_ID = #{mdfrId}
    , MOD_DTTM = FN_DTTM()
WHERE
    RUBRIC_ID = #{rubricId}
    AND ORG_ID = #{orgId}
    AND RUBRIC_TYCD = 'ORG'

mapper.delete:
DELETE FROM TB_LMS_RUBRIC_QSTN
WHERE RUBRIC_ID IN (
    SELECT RUBRIC_ID
    FROM TB_LMS_RUBRIC
    WHERE RUBRIC_ID = #{rubricId}
      AND ORG_ID = #{orgId}
      AND RUBRIC_TYCD = 'ORG'
)

DELETE FROM TB_LMS_RUBRIC_VWITM
WHERE RUBRIC_QSTN_ID IN (
    SELECT QSTN.RUBRIC_QSTN_ID
    FROM TB_LMS_RUBRIC_QSTN QSTN
    JOIN TB_LMS_RUBRIC RBRC
      ON QSTN.RUBRIC_ID = RBRC.RUBRIC_ID
    WHERE RBRC.RUBRIC_ID = #{rubricId}
      AND RBRC.ORG_ID = #{orgId}
      AND RBRC.RUBRIC_TYCD = 'ORG'
)
